content.text:
.scoreboard{position:absolute;z-index:2;top:104px;left:4.2%;display:flex;align-items:flex-start;gap:22px;padding:14px 18px 14px 0;background:linear-gradient(90deg,rgba(5,24,22,.86),rgba(5,24,22,.68));border:1px solid rgba(240,231,207,.15);border-left:2px solid var(--gold);backdrop-filter:blur(8px);box-shadow:0 8px 26px #071a1a38}

.over-strip{z-index:2;position:absolute;top:108px;right:4.3%;height:43px;display:flex;align-items:center;gap:14px;padding:0 13px;background:rgba(5,24,22,.72);border:1px solid rgba(240,231,207,.14);backdrop-filter:blur(8px)}

.delivery-callout{position:absolute;z-index:2;left:50%;top:63%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;color:#f5e7c9;text-shadow:0 2px 10px #081c16;font:9px 'DM Mono',monospace;letter-spacing:2.1px;opacity:0;transition:opacity .2s;white-space:nowrap}

.bottom-ui{z-index:3;position:absolute;bottom:55px;left:4.2%;right:4.2%;display:flex;align-items:flex-end;justify-content:space-between}

.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(4,18,17,.37);backdrop-filter:blur(2px);transition:opacity .35s,visibility .35s}

input.newString:
@media(max-height:650px){.scoreboard{top:88px}.over-strip{top:92px}.bottom-ui{bottom:44px}.bottom-foot{height:30px}.shot-btn{height:65px}.swing-button{height:59px}}
.challenge-panel{position:absolute;z-index:2;top:108px;left:50%;transform:translateX(-50%);width:226px;padding:10px 13px 9px;background:rgba(5,24,22,.78);border:1px solid rgba(240,231,207,.2);border-top:2px solid var(--gold);backdrop-filter:blur(8px);box-shadow:0 8px 26px #071a1a38;text-align:center;transition:border-color .2s,background .2s}
.challenge-panel strong,.challenge-panel span,.challenge-panel small{display:block}
.challenge-kicker{color:var(--gold);font:8px 'DM Mono',monospace;letter-spacing:1.6px}
.challenge-panel strong{margin:3px 0;color:var(--cream);font-size:11px;letter-spacing:1.4px}
.challenge-panel>span:not(.challenge-kicker){color:#c3cabc;font:9px 'DM Mono',monospace;letter-spacing:.25px}
.challenge-meter{height:3px;margin:8px 0 5px;background:rgba(255,255,255,.15)}
.challenge-meter i{display:block;width:0;height:100%;background:var(--gold);transition:width .25s ease}
.challenge-panel small{color:#aab5a8;font:8px 'DM Mono',monospace;letter-spacing:1px}
.challenge-panel.completed{border-top-color:#a9c897;background:rgba(24,56,39,.88)}
.challenge-panel.completed .challenge-meter i{background:#a9c897}
@media(max-width:850px){.challenge-panel{top:126px;width:205px;padding:7px 10px}.challenge-panel strong{font-size:10px}.challenge-meter{margin:5px 0 3px}}
@media(max-width:560px){.challenge-panel{top:117px;width:184px;padding:6px 8px}.challenge-kicker{font-size:7px}.challenge-panel strong{margin:2px 0;font-size:9px}.challenge-panel>span:not(.challenge-kicker){font-size:8px}.challenge-meter{margin:4px 0 2px}.challenge-panel small{font-size:7px}}

