mkdir -p /tmp/opencode && cat > /tmp/opencode/verify-cricket.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true, args:['--no-sandbox','--enable-webgl','--ignore-gpu-blocklist']});
  const page = await browser.newPage({viewport:{width:1280,height:800}, deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
  await page.goto('http://localhost:3002', {waitUntil:'networkidle',timeout:45000});
  await page.locator('#startBtn').click();
  await page.waitForTimeout(1200);
  await page.screenshot({path:'/tmp/opencode/cricket-latest.png'});
  const firstSpeed=await page.locator('#speed').innerText();
  await page.locator('.shot-btn[data-shot="loft"]').click();
  for(let i=0;i<6;i++){
    await page.waitForFunction(()=>document.querySelector('#calloutText').textContent.includes('PLAY YOUR SHOT') || document.querySelector('#resultOverlay').classList.contains('hidden')===false,{},{timeout:10000});
    if(!(await page.locator('#resultOverlay').evaluate(el=>el.classList.contains('hidden'))))break;
    await page.keyboard.press('Space');
    await page.waitForFunction((expected)=>document.querySelectorAll('#ballTrack i:not(.empty-ball)').length >= expected || !document.querySelector('#resultOverlay').classList.contains('hidden'),i+1,{timeout:10000});
  }
  const result={firstSpeed,score:await page.locator('#score').innerText(),overs:await page.locator('#overs').innerText(),challenge:await page.locator('#challengeName').innerText(),challengeProgress:await page.locator('#challengeProgress').innerText(),errors};
  await page.locator('#resetBtn').click();
  result.resetScore=await page.locator('#score').innerText();
  result.startOverlayVisible=!(await page.locator('#startOverlay').evaluate(el=>el.classList.contains('hidden')));
  console.log(JSON.stringify(result,null,2));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
