  await page.locator('#startBtn').click();
  await page.waitForFunction(()=>document.querySelector('#speed').textContent!=='—',{timeout:15000});
  await page.waitForTimeout(500);
  await page.screenshot({path:'/tmp/opencode/cricket-latest.png'});
  const speeds=[138,132,146,141,112,134];
  await page.locator('.shot-btn[data-shot="loft"]').click();
  for(let i=0;i<6;i++){
    await page.waitForFunction(()=>document.querySelector('#calloutText').textContent==='PLAY YOUR SHOT',{timeout:30000});
    await page.keyboard.press('Space');
    if(i<5) await page.waitForFunction((speed)=>document.querySelector('#speed').textContent===String(speed),speeds[i+1],{timeout:30000});
  }
  await page.waitForFunction(()=>document.querySelector('#challengeName').textContent==='RUN RATE',{timeout:30000});
  const result={speedSequence:speeds,score:await page.locator('#score').innerText(),overs:await page.locator('#overs').innerText(),nextChallenge:await page.locator('#challengeName').innerText(),progress:await page.locator('#challengeProgress').innerText(),errors};
  await page.locator('#resetBtn').click();
  result.resetScore=await page.locator('#score').innerText();
  result.startOverlayVisible=!(await page.locator('#startOverlay').evaluate(el=>el.classList.contains('hidden')));
  result.resetChallenge=await page.locator('#challengeName').innerText();
  console.log(JSON.stringify(result,null,2));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
