 while(Date.now()-after<18000){
   states.push(await p.evaluate(()=>({phase:window.__cricketState.phase,hit:window.__cricketState.delivery?.hit,flight:window.__cricketState.delivery?.flight,balls:window.__cricketState.balls,score:window.__cricketState.score,callout:document.querySelector('#calloutText').textContent,speed:document.querySelector('#speed').textContent})));
