cat > /tmp/opencode/finish-check.cjs <<'EOF'
const {chromium}=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const b=await chromium.launch({channel:'chromium',headless:false,args:['--enable-gpu','--ignore-gpu-blocklist','--use-vulkan=swiftshader','--disable-vulkan-surface']});const p=await b.newPage({viewport:{width:1280,height:800}});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.route('**/game.js',async route=>{const r=await route.fetch();await route.fulfill({response:r,body:(await r.text())+'\nwindow.__cricketTest={state,resolveBall};'});});await p.goto('http://localhost:3002',{waitUntil:'networkidle'});await p.locator('#startBtn').click();await p.waitForFunction(()=>window.__cricketTest);await p.evaluate(()=>{const s=window.__cricketTest.state;s.score=32;s.phase='delivery';s.delivery={hit:true,quality:1,result:4};window.__cricketTest.resolveBall()});const result={title:await p.locator('#resultTitle').innerText(),score:await p.locator('#finalScore').innerText(),visible:await p.locator('#resultOverlay').evaluate(e=>!e.classList.contains('hidden')),errors};console.log(JSON.stringify(result,null,2));await b.close()})().catch(e=>{console.error(e);process.exit(1)});
EOF
DISPLAY=:0 node /tmp/opencode/finish-check.cjs

